            Some(path) => crate::harvest::sign::verify_sig_at(pack_dir, &path, &public),
            None => Err(anyhow::anyhow!(
                "no SHA256SUMS.sig to verify — not in the pack, and no \
                 {}-SHA256SUMS.sig beside {}",
                meta.name,
                share_path
            )),
